from typing import List

def optimized_shell_sort(arr: List[int]) -> List[int]:
    if not arr:
        return arr
    n = len(arr)
    k = 1
    gaps = []
    while 2 ** k - 1 < n:
        gaps.append(2 ** k - 1)
        k += 1
    gaps.reverse()
    for gap in gaps:
        for i in range(gap, n):
            temp = arr[i]
            j = i
            while j >= gap and arr[j - gap] > temp:
                arr[j] = arr[j - gap]
                j -= gap
            arr[j] = temp
    return arr

