        queue = [(src, 0)]
        visited = set([src])
        while queue:
            cur, steps = queue.pop(0)
            for neighbor in graph[cur]:
                if neighbor == dest:
                    return steps + 1
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, steps + 1))
