import collections

def process_queries(N, M, Q, values, edges, queries):
    graph = collections.defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dfs_sum(current, target, visited):
        if current == target:
            return values[current - 1]
        visited.add(current)
        for neighbor in graph[current]:
            if neighbor not in visited:
                result = dfs_sum(neighbor, target, visited)
                if result is not None:
                    return values[current - 1] + result
        return None
