def find_next_tallest_building(heights):
    if not heights:
        return []
    n = len(heights)
    result = [-1] * n
    stack = []
    for i in range(n - 1, -1, -1):
        while stack and heights[stack[-1]] <= heights[i]:
            stack.pop()
        if stack:
            result[i] = stack[-1]
        stack.append(i)
    return result
